// V1 has no plugin hot reload: a REG change needs an OpenCode restart, a guard_config.json change does not.
import { spawn } from "node:child_process"
import { readFileSync } from "node:fs"
import { dirname, isAbsolute, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

// Repo root from this file's location: ctx.worktree is "/" outside git (project.ts:217@v1.19.0).
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..")
const REG = {"post_tool_use":{"timeout_ms":12000,"tools":["apply_patch","edit","write"]},"pre_tool_use":{"timeout_ms":7000,"tools":["apply_patch","bash","edit","write"]},"session_start":{"timeout_ms":4000},"stop":{"timeout_ms":5000}}
const TOOL = { bash: "Bash", edit: "Edit", write: "Write", read: "Read", glob: "Glob", grep: "Grep",
  webfetch: "WebFetch", websearch: "WebSearch", task: "Agent", todowrite: "TodoWrite",
  question: "AskUserQuestion", skill: "Skill" }           // apply_patch and MCP/plugin tools pass through
const ALIAS = { filePath: "file_path", oldString: "old_string", newString: "new_string",
  replaceAll: "replace_all", patchText: "patch_text", include: "glob" }
const EVENT = { pre_tool_use: "PreToolUse", post_tool_use: "PostToolUse",
  session_start: "SessionStart", stop: "Stop" }
const RESP_CAP = 65536    // tool output forwarded to post_tool_use
const NONE = { decision: "none", reason: "", context: "", notice: "" }
const deferred = new Map() // callID -> pre_tool_use context, appended to that call's result
const system = new Map()   // sessionID -> Promise of the session_start text, re-pushed on every model request
const carry = new Map()    // sessionID -> last stop findings, replaced at the next session.idle
const notes = new Map()    // sessionID -> wire `notice` lines, pushed once on the next model request

// @@wire-parse:begin
// playbook.hook.wire/1 (§D.3.5): a test runs this slice under node and pins a Python port to its sha256.
const CAP = 4000          // hard ceiling per injected block; the dispatcher's own caps are lower
let warned = false

function inactive(why) {   // fail open; say so once per process
  if (!warned) { warned = true; console.error(`[playbook] lifecycle hooks inactive: ${why}; run 'playbook-hook doctor'`) }
  return { decision: "none", reason: "", context: "", notice: "", failed: why }
}

// wire/1 fields are strings: anything else is dropped, never String()-coerced, which can throw
// (an object with a non-callable toString) inside the child's close listener, past every catch.
const str = (v) => (typeof v === "string" ? v : "")

function parse(code, out) {   // exit 10 = decided deny; a raw 2 (usage, interpreter error) is not a deny
  if (code !== 0 && code !== 10) return inactive(`dispatcher exited ${code}`)
  const text = out.trim()
  let j = {}
  if (text) {
    try { j = JSON.parse(text) } catch { j = null }
    if (j === null || typeof j !== "object" || Array.isArray(j)) return inactive("dispatcher wrote non-JSON stdout")
  }
  const deny = code === 10 || j.decision === "deny"   // ask was already degraded to deny (§D.3.6); "allow" does not exist (L6)
  return {
    decision: deny ? "deny" : "none",
    reason: str(j.reason).trim() || (deny ? "Blocked by a playbook hook." : ""),
    context: (Array.isArray(j.context) ? j.context.filter((c) => typeof c === "string").join("\n") : "").slice(0, CAP),
    notice: str(j.notice).slice(0, CAP),
  }
}
// @@wire-parse:end

const own = (table, key) => (Object.hasOwn(table, key) ? table[key] : undefined)
const listed = (tools, tool) => tools === "*" || (Array.isArray(tools) && tools.includes(tool))
const wants = (event, tool) => listed(REG[event]?.tools, tool)
const note = (sid, r) => { if (sid && r.notice) notes.set(sid, [...(notes.get(sid) ?? []), r.notice].slice(-5)) }

function interpreter() {   // the per-worktree pin `playbook sync` writes under the git dir (§C.2.7)
  let gitdir = join(ROOT, ".git")
  try {
    const m = /^gitdir:\s*(.+?)\s*$/m.exec(readFileSync(gitdir, "utf8"))   // a linked worktree's .git file
    if (m) gitdir = isAbsolute(m[1]) ? m[1] : resolve(ROOT, m[1])
  } catch { /* .git is a directory (EISDIR) or absent */ }
  try {
    const py = readFileSync(join(gitdir, "playbook-hooks", "interpreter"), "utf8").split(/\r?\n/)[0].trim()
    return isAbsolute(py) ? py : null
  } catch { return null }
}

function dispatch(event, payload) {   // async spawn under the shim's own deadline: OpenCode never times a hook out
  const py = interpreter()
  if (!py) return Promise.resolve(inactive("no interpreter pin (run 'playbook sync')"))
  const limit = REG[event].timeout_ms
  return new Promise((done) => {
    let out = "", timer = null, settled = false
    const finish = (r) => { if (!settled) { settled = true; clearTimeout(timer); done(r) } }
    let child
    try {
      child = spawn(py, ["-I", "-m", "coding_agent_playbook.hook_runtime", "dispatch", event,
        "--harness", "opencode", "--project-dir", ROOT],
        { cwd: ROOT, shell: false, windowsHide: true, stdio: ["pipe", "pipe", "pipe"] })
    } catch (e) { return finish(inactive(`spawn failed (${e.code ?? e.message})`)) }
    timer = setTimeout(() => { child.kill(); finish(inactive(`${event} exceeded ${limit} ms`)) }, limit)
    child.stdout.setEncoding("utf8").on("data", (d) => { out += d })
    child.stderr.resume()                               // drained, so a chatty dispatcher never blocks on the pipe
    child.stdin.on("error", () => {})                   // EPIPE when the dispatcher exits without reading
    child.on("error", (e) => finish(inactive(`spawn failed (${e.code ?? e.message})`)))
    child.on("close", (code) => finish(parse(code, out)))
    child.stdin.end(JSON.stringify(payload))
  })
}

function fire(event, payload) {   // OQ-19's async audit dispatch: never awaited, its output ignored
  const py = interpreter()
  if (!py) return
  try {
    const child = spawn(py, ["-I", "-m", "coding_agent_playbook.hook_runtime", "dispatch", event,
      "--harness", "opencode", "--project-dir", ROOT, "--async"],
      { cwd: ROOT, shell: false, windowsHide: true, stdio: ["pipe", "ignore", "ignore"] })
    child.on("error", () => {})                         // a lost audit line never fails the tool call
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  } catch { /* spawn failed: fail open */ }
}

async function safely(step) {   // a fault in the shim itself fails open, like any harness-level failure
  try { return (await step()) ?? NONE } catch (e) { return inactive(`shim error (${e?.message ?? e})`) }
}

const toolInput = (args) => {      // a deep copy: the shim never mutates output.args (L6: no updatedInput)
  const input = JSON.parse(JSON.stringify(args ?? {}))
  for (const [native, alias] of Object.entries(ALIAS)) if (native in input && !(alias in input)) input[alias] = input[native]
  return input
}
const toolPayload = (event, input, args, extra) => ({
  hook_event_name: EVENT[event], session_id: input.sessionID, tool_use_id: input.callID,
  tool_name: own(TOOL, input.tool) ?? input.tool, tool_input: toolInput(args), cwd: ROOT, ...extra })

async function beforeTool(input, output) {
  if (!wants("pre_tool_use", input.tool)) return NONE
  const r = await dispatch("pre_tool_use", toolPayload("pre_tool_use", input, output.args, {}))
  note(input.sessionID, r)
  if (r.decision !== "deny" && r.context) {   // a denied call carries its context in the reason
    deferred.set(input.callID, r.context)
    if (deferred.size > 256) deferred.delete(deferred.keys().next().value)   // after() never fires on failure
  }
  return r
}

async function afterTool(input, output) {
  let ctx = deferred.get(input.callID) ?? ""
  deferred.delete(input.callID)
  if (listed(REG.post_tool_use?.async, input.tool)) {   // before the shape check: every tool is audited
    fire("post_tool_use", toolPayload("post_tool_use", input, input.args, { tool_response: { title: output?.title ?? "" } }))
  }
  if (typeof output.output !== "string") return   // MCP CallToolResult shapes are left untouched
  if (wants("post_tool_use", input.tool)) {
    const r = await dispatch("post_tool_use", toolPayload("post_tool_use", input, input.args,
      { tool_response: { output: output.output.slice(0, RESP_CAP), title: output.title ?? "" } }))
    note(input.sessionID, r)
    if (r.context) ctx = ctx ? `${ctx}\n${r.context}` : r.context
  }
  if (ctx) output.output += `\n\n[playbook] ${ctx}`
}

async function briefing(sid) {   // session_start, once per session: its context, or the inactive notice
  const r = await safely(() => dispatch("session_start",
    { hook_event_name: "SessionStart", session_id: sid, source: "startup", cwd: ROOT }))
  note(sid, r)
  return r.failed
    ? `playbook lifecycle hooks are NOT active this session (${r.failed}); apply the AGENTS.md Guardrails section yourself.`
    : r.context
}

async function transform(input, output) {   // the session context, the stop carry, then queued notices
  const sid = input.sessionID
  if (!sid) return
  if (REG.session_start && !system.has(sid)) system.set(sid, briefing(sid))
  const brief = await system.get(sid)
  for (const text of [brief, carry.get(sid), ...(notes.get(sid) ?? [])]) if (text) output.system.push(text)
  notes.delete(sid)
}

async function idle(event) {   // the Stop coordinator, evidence-only: session.idle cannot block (§C.3.6)
  if (event?.type !== "session.idle" || !REG.stop) return
  const sid = event.properties?.sessionID
  if (!sid) return
  const r = await dispatch("stop", { hook_event_name: "Stop", session_id: sid, stop_hook_active: false, cwd: ROOT })
  note(sid, r)   // the dispatcher returns the combined Stop result on stdout; carry is its only carrier
  const text = r.decision === "deny" ? `The previous turn ended with unresolved playbook gate findings:\n${r.reason}` : r.context
  if (text) carry.set(sid, text.slice(0, CAP)); else carry.delete(sid)
}

async function server() {
  return {
    "tool.execute.before": async (input, output) => {
      const r = await safely(() => beforeTool(input, output))
      if (r.decision === "deny") throw new Error(r.reason)   // becomes the tool's error result; the loop continues
    },
    "tool.execute.after": async (input, output) => { await safely(() => afterTool(input, output)) },
    "experimental.chat.system.transform": async (input, output) => { await safely(() => transform(input, output)) },
    event: async (arg) => { await safely(() => idle(arg?.event)) },   // fire-and-forget: OpenCode does not await it
  }
}

